# Staged upstream tarballs, not Homebrew bottles. Generated by tools/homebrew_formula.py.
require "json"

class Zpq < Formula
  desc "Fast Unix-native Parquet inspection, filtering and projection"
  homepage "https://github.com/chicagobuss/zpq"
  license "MIT"

  on_macos do
    depends_on arch: :arm64
    on_arm do
      url "https://github.com/chicagobuss/zpq/releases/download/v0.5.1/zpq-aarch64-macos.tar.gz"
      sha256 "363759253e9f61f8ff7989fd426716522d44d3b280343bd2ceee3234dbac0f67"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/chicagobuss/zpq/releases/download/v0.5.1/zpq-aarch64-linux-musl.tar.gz"
      sha256 "7b4ec804633ae724930218ffb9f82609f2c981acf669363b530c118eae320db1"
    end
    on_intel do
      url "https://github.com/chicagobuss/zpq/releases/download/v0.5.1/zpq-x86_64-linux-musl.tar.gz"
      sha256 "5d482f830737fde47e0446ab33c67dd3fa45076aa792fb9331ac87803efa2c79"
    end
  end

  def install
    bin.install "bin/zpq"
    bash_completion.install "share/bash-completion/completions/zpq"
    zsh_completion.install "share/zsh/site-functions/_zpq"
    fish_completion.install "share/fish/vendor_completions.d/zpq.fish"
    man1.install "share/man/man1/zpq.1"
    doc.install Dir["share/doc/zpq/*"]
    pkgshare.install "share/zpq/tiny.parquet"
    pkgshare.install "MANIFEST.json"
  end

  test do
    file = pkgshare/"tiny.parquet"
    filtered = JSON.parse(shell_output("#{bin}/zpq query #{file} --filter 'id = 2' --columns id,value"))
    assert_equal({ "id" => 2, "value" => 20 }, filtered)
    groups = shell_output("#{bin}/zpq query #{file} --group-by group --aggregate 'sum(value) AS total'")
    assert_equal [{ "group" => "a", "total" => 30 }, { "group" => "b", "total" => 30 }],
                 groups.lines.map { |line| JSON.parse(line) }
  end
end
